Translate("zhCN", "un-goro-crater", {
	title = "安戈洛环形山",
	aliases = { "安戈洛", "环形山" },
	sections = {
		{
			title = "概述",
			text = [=[安戈洛环形山是深陷于{link:kalimdor}卡利姆多{/link}南部的一个巨大的绿色盆地，四周峭壁环绕，夹在{link:tanaris}塔纳利斯{/link}的沙漠与{link:silithus}希利苏斯{/link}的枯萎荒原之间。在它的边缘之下，世界仿佛属于另一个时代。温泉蒸汽升腾，中央的火山冒着浓烟，丛林由世上其他地方早已遗忘的野兽主宰：声如{link:farmer-ray}雷{/link}鸣的魔暴龙、剑龙、展翼的翼手龙和成群的暴掠龙。奇异的水晶在草丛中闪闪发光，高大的{link:crystal-pylons}水晶塔{/link}矗立在荒野的边缘。]=],
