Translate("zhCN", "lakkari-tar-pits", {
	title = "拉卡利油沼",
	aliases = { "拉卡利" },
	sections = {
		{
			title = "概述",
			text = [=[拉卡利油沼位于{link:un-goro-crater}环形山{/link}北部，在{link:marshal-s-refuge}马绍尔营地{/link}以南。黑色的焦油从地下冒出，形成宽阔而黏稠的油池。从中升起的焦油生物似乎有自己的生命，能凭自己的意志行动。其中最强大的焦油领主潜伏在北部的油池附近。较弱的焦油兽和焦油爬行者则向南游荡，一直到火山下方的{link:burning-steppes}平原{/link}。没有记录说明是谁给这些油沼起了名字。]=],
