	sections = {
		{
			title = "概述",
			text = [=[巨痕谷是{link:un-goro-crater}环形山{/link}南部地面上一道巨大的裂谷，戈里什的虫子在那里筑起了巢穴。黄蜂充斥着它上方的天空，工虫、掠夺者和掘地虫在它的通道中爬行。在挂满幼虫卵的深处巢室里，虫巢繁育着它的后代，一位女王在其中统治着它们。远征队逃离时，{link:hol-anyee-marshal}霍莱伊·马绍尔{/link}正在研究戈里什。在她看来，它们根本不属于这座环形山。]=],
		},
	},
})

Translate("zhCN", "terror-run", {
