Translate("zhCN", "fungal-rock", {
	title = "蘑菇石",
	sections = {
		{
			title = "概述",
			text = [=[蘑菇石是{link:un-goro-crater}环形山{/link}东北部的一片洞穴，是安戈洛巨猿的巢穴。猩猩、践踏者和{link:farmer-ray}雷{/link}吼者守卫着它，其中最凶猛的是{link:tauren}牛头人{/link}猎人{link:torwa-pathfinder}托尔瓦{/link}称为乌卡的那头强大巨猿。发明家{link:karna-remtravel}卡尔纳·雷塔维{/link}把她的机械猿{link:a-me-01}阿米 01{/link}送进这些洞穴，近距离观察猿群。猿群并没有被骗多久。当旅人们再次找到她时，她静静地躺在洞口，身上满是凹痕。]=],
		},
	},
