Translate("zhCN", "the-marshlands", {
	title = "沼泽地",
	sections = {
		{
			title = "概述",
			text = [=[沼泽地是{link:un-goro-crater}环形山{/link}东部潮湿的低地，一片泥泞、芦苇和死水的地方。各种黏液怪聚集在它的水池中，血瓣花在它的灌木丛中蔓延。远征队的一座废弃营地就位于环形山的这一侧，探险者们逃走很久之后，营地的储备仍原封不动地留在泥里。再往南，一个小池塘边停着一只破损的木筏，周围根本没有能把它带到那里的水域。它属于流浪者{link:linken}林克{/link}，尽管他已经不记得了。]=],
		},
	},
})

Translate("zhCN", "crystal-pylons", {
	title = "水晶塔",
	aliases = { "安戈洛的水晶塔" },
	sections = {
		{
			title = "概述",
			text = [=[{link:un-goro-crater}安戈洛环形山{/link}的荒野中矗立着三座水晶塔：一座在北方，一座靠着东壁，一座在西方。它们是高大的石制建筑，内壁镶嵌着水晶，比任何在世的探险者的营地都要古老得多。很长一段时间里，它们只是{link:marshal-s-refuge}马绍尔营地{/link}里流传的传闻。]=],
		},
		{
			title = "水晶",
			text = [=[彩色的水晶散布在{link:un-goro-crater}环形山{/link}的地面上：红色、蓝色、黄色和绿色。大多数旅人对它们视而不见。{link:gnomes}侏儒{/link}{link:j-d-collie}科琳{/link}却不然。她一袋一袋地收集它们，尝试了她能想到的每一种组合，但在水晶塔被找到之前，它们什么也没有透露。旅人们考察了全部三座塔之后，她把他们所见的一切仔细推敲，并把她的发现写成了一本手册。借助它，水晶可以被熔合成各种组合，为携带者恢复、强化、防护和充能。]=],
		},
		{
			title = "悬而未解",
			text = [=[是谁建造了这些水晶塔，又是为了什么目的，{link:un-goro-crater}环形山{/link}没有给出答案。{link:j-d-collie}科琳{/link}学会了如何使用它们的水晶。她没有弄明白它们为什么会在那里。]=],
		},
	},
})

